phase1.code:
# FizzBuzz — the classic coding challenge

# Classic FizzBuzz: 1-20
# Print number, but:
# - If divisible by 3: print "Fizz"
# - If divisible by 5: print "Buzz"
# - If divisible by both: print "FizzBuzz"

print("Classic FizzBuzz 1-20:")
for i in range(1, 21):
    if i % 3 == 0 and i % 5 == 0:
        print("FizzBuzz", end=" ")
    elif i % 3 == 0:
        print("Fizz", end=" ")
    elif i % 5 == 0:
        print("Buzz", end=" ")
    else:
        print(i, end=" ")

print("\n")

# FizzBuzz with a function
def fizzbuzz(n):
    if n % 15 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)

print("Using function:")
for i in range(1, 16):
    print(fizzbuzz(i), end=" ")

print("\n")

# FizzBuzz with list comprehension
results = [fizzbuzz(i) for i in range(1, 16)]
print(f"List comprehension: {results}")

print("\n")

# More creative: FizzBuzz with "player level"
# Instead of numbers, use player levels
print("Player Level FizzBuzz:")
for level in range(1, 21):
    if level % 3 == 0 and level % 5 == 0:
        print("Dragon Slayer!", end=" ")
    elif level % 3 == 0:
        print("Knight", end=" ")
    elif level % 5 == 0:
        print("Ranger", end=" ")
    else:
        print(f"Level {level}", end=" ")

